/* EMBEDDED_JETBRAINS_MONO_BEGIN */
@font-face {
    font-family: "JetBrainsMono Nerd Embedded";
    src: url("data:font/ttf;base64,") format("truetype");
    font-style: normal;
    font-weight: 100 900;
    font-display: swap;
}
/* EMBEDDED_JETBRAINS_MONO_END */

:root {
    --polar-void: #070B12;
    --control-navy: #111A27;
    --snow-white: #F4F7FB;
    --signal-cyan: #54C7EC;
    --tuna-amber: #F6B83F;
    --alarm-coral: #FF657A;
    --font-display: "JetBrainsMono Nerd Embedded", "Malgun Gothic", "Apple SD Gothic Neo", "Noto Sans KR", system-ui, sans-serif;
    --font-body: "JetBrainsMono Nerd Embedded", "Malgun Gothic", "Apple SD Gothic Neo", "Noto Sans KR", system-ui, sans-serif;
    --font-utility: "JetBrainsMono Nerd Embedded", "Malgun Gothic", Consolas, "SFMono-Regular", "Liberation Mono", monospace;
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

html {
    background: var(--polar-void);
}

body {
    min-width: 0;
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 16px;
    background: var(--polar-void);
    color: var(--snow-white);
    font-family: var(--font-body);
    line-height: 1.5;
}

button {
    font: inherit;
}

header {
    width: 100%;
    max-width: 960px;
    margin-bottom: 16px;
    text-align: left;
}

h1,
h2,
h3 {
    font-family: var(--font-display);
}

h1 {
    position: relative;
    overflow: hidden;
    color: var(--snow-white);
    font-size: clamp(1.5rem, 5vw, 2.25rem);
    font-weight: 800;
    letter-spacing: -0.04em;
    line-height: 1.15;
    text-overflow: clip;
    white-space: nowrap;
}

h1::before {
    content: "SYS // ANTARCTIC OPS";
    display: block;
    position: absolute;
    top: 4px;
    right: 0;
    color: var(--signal-cyan);
    font-family: var(--font-utility);
    font-size: 0.66rem;
    font-weight: 600;
    letter-spacing: 0.12em;
}

.brand-code {
    color: var(--signal-cyan);
    font-family: var(--font-utility);
    font-variant-numeric: tabular-nums;
    letter-spacing: -0.02em;
}

.sub {
    max-width: 42rem;
    margin-top: 4px;
    overflow: hidden;
    color: var(--snow-white);
    display: -webkit-box;
    font-size: 0.82rem;
    line-height: 1.45;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
}

.dashboard {
    width: 100%;
    max-width: 960px;
    min-width: 0;
    display: grid;
    grid-template-columns: repeat(6, minmax(0, 1fr));
    gap: 8px;
    margin-bottom: 16px;
}

.card {
    min-width: 0;
    padding: 12px 8px;
    overflow: hidden;
    background: var(--control-navy);
    border: 1px solid var(--signal-cyan);
    border-radius: 4px;
    text-align: left;
}

.card-title {
    overflow: hidden;
    color: var(--snow-white);
    font-size: 0.68rem;
    font-weight: 700;
    letter-spacing: 0.06em;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.card-val {
    margin-top: 4px;
    overflow-wrap: anywhere;
    color: var(--signal-cyan);
    font-family: var(--font-utility);
    font-size: 1rem;
    font-variant-numeric: tabular-nums;
    font-weight: 700;
    line-height: 1.25;
}

#val-stars,
#val-tuna {
    color: var(--tuna-amber);
}

#val-debt,
#val-threat,
#val-cost {
    color: var(--alarm-coral);
}

.intrusion-banner {
    width: 100%;
    max-width: 960px;
    margin-bottom: 16px;
    padding: 16px;
    background: var(--control-navy);
    border: 2px solid var(--alarm-coral);
    border-radius: 8px;
    text-align: left;
}

@keyframes intrusion-impact-copilot {
    0%, 100% { transform: translate3d(0, 0, 0); }
    25% { transform: translate3d(3px, 0, 0); }
    50% { transform: translate3d(-3px, 0, 0); }
    75% { transform: translate3d(3px, 0, 0); }
}

@keyframes intrusion-impact-codex {
    0%, 100% { transform: translate3d(0, 0, 0); }
    25% { transform: translate3d(4px, 1px, 0); }
    50% { transform: translate3d(-4px, -1px, 0); }
    75% { transform: translate3d(4px, 1px, 0); }
}

@keyframes intrusion-impact-gemini {
    0%, 100% { transform: translate3d(0, 0, 0); }
    15%, 25% { transform: translate3d(2px, 0, 0); }
    35% { transform: translate3d(-2px, 0, 0); }
    45%, 55% { transform: translate3d(2px, 0, 0); }
    65% { transform: translate3d(-2px, 0, 0); }
    75%, 85% { transform: translate3d(2px, 0, 0); }
}

@keyframes intrusion-impact-ceo {
    0%, 100% { transform: translate3d(0, 0, 0); }
    25% { transform: translate3d(5px, 1px, 0); }
    50% { transform: translate3d(-5px, -1px, 0); }
    75% { transform: translate3d(5px, 1px, 0); }
}

body.intrusion-impact--copilot > header,
body.intrusion-impact--copilot > .dashboard,
body.intrusion-impact--copilot > .intrusion-banner,
body.intrusion-impact--copilot > .main-grid {
    animation: intrusion-impact-copilot 320ms linear 1 both;
    will-change: transform;
}

body.intrusion-impact--codex > header,
body.intrusion-impact--codex > .dashboard,
body.intrusion-impact--codex > .intrusion-banner,
body.intrusion-impact--codex > .main-grid {
    animation: intrusion-impact-codex 420ms linear 1 both;
    will-change: transform;
}

body.intrusion-impact--gemini > header,
body.intrusion-impact--gemini > .dashboard,
body.intrusion-impact--gemini > .intrusion-banner,
body.intrusion-impact--gemini > .main-grid {
    animation: intrusion-impact-gemini 650ms linear 1 both;
    will-change: transform;
}

body.intrusion-impact--ceo > header,
body.intrusion-impact--ceo > .dashboard,
body.intrusion-impact--ceo > .intrusion-banner,
body.intrusion-impact--ceo > .main-grid {
    animation: intrusion-impact-ceo 520ms linear 1 both;
    will-change: transform;
}

.intrusion-title {
    color: var(--alarm-coral);
    font-family: var(--font-utility);
    font-size: 1rem;
    font-weight: 800;
}

.intrusion-msg {
    margin: 8px 0 12px;
    color: var(--snow-white);
    font-size: 0.88rem;
}

.intrusion-actions {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
}

.main-grid {
    width: 100%;
    max-width: 960px;
    min-width: 0;
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
    gap: 16px;
}

.panel {
    min-width: 0;
    padding: 16px;
    background: var(--control-navy);
    border: 1px solid var(--signal-cyan);
    border-radius: 8px;
}

.panel h2 {
    font-size: 1rem;
    font-weight: 800;
    letter-spacing: -0.02em;
}

.panel h3 {
    font-size: 0.84rem;
    font-weight: 700;
}

.btn-touch,
.tab-btn,
.puzzle-option {
    min-width: 48px;
    min-height: 48px;
    border-radius: 4px;
    cursor: pointer;
    transition: background-color 100ms ease, border-color 100ms ease, color 100ms ease;
}

.btn-touch {
    padding: 12px 16px;
    background: var(--control-navy);
    border: 1px solid var(--signal-cyan);
    color: var(--snow-white);
    font-family: var(--font-utility);
    font-size: 0.9rem;
    font-variant-numeric: tabular-nums;
    font-weight: 800;
}

.btn-touch:hover:not(:disabled) {
    border-color: var(--signal-cyan);
}

.btn-touch:focus-visible,
.tab-btn:focus-visible,
.puzzle-option:focus-visible,
.terminal-output:focus-visible {
    outline: 2px solid var(--signal-cyan);
    outline-offset: 4px;
}

.btn-touch:disabled {
    cursor: not-allowed;
    opacity: 0.52;
}

.btn-danger,
.is-produce {
    background: var(--signal-cyan);
    border-color: var(--signal-cyan);
    color: var(--polar-void);
}

.btn-warning,
.is-locked {
    background: var(--alarm-coral);
    border-color: var(--alarm-coral);
    color: var(--polar-void);
}

.btn-success,
.is-recover {
    background: var(--tuna-amber);
    border-color: var(--tuna-amber);
    color: var(--polar-void);
}

.is-complete {
    background: var(--snow-white);
    border-color: var(--signal-cyan);
    color: var(--polar-void);
}

.is-complete:disabled,
.is-locked:disabled {
    opacity: 1;
}

.stage-badge {
    display: inline-block;
    max-width: 100%;
    margin-top: 12px !important;
    padding: 8px 12px;
    overflow-wrap: anywhere;
    background: var(--polar-void);
    border: 1px solid var(--signal-cyan);
    border-radius: 4px;
    color: var(--signal-cyan);
    font-family: var(--font-utility);
    font-size: 0.76rem;
    font-variant-numeric: tabular-nums;
    font-weight: 700;
}

#shelter-stage-display {
    position: relative;
    isolation: isolate;
    min-height: 160px;
    margin: 16px 0 !important;
    padding: 32px 16px !important;
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
    background: var(--polar-void);
    border: 1px solid var(--signal-cyan);
    border-radius: 4px;
    outline: 1px dashed var(--signal-cyan);
    outline-offset: -8px;
    color: var(--snow-white);
    font-size: clamp(2.75rem, 8vw, 4rem) !important;
    line-height: 1;
}

#shelter-stage-display::before,
#shelter-stage-display::after {
    position: absolute;
    z-index: 1;
    padding: 4px 8px;
    background: var(--polar-void);
    color: var(--signal-cyan);
    font-family: var(--font-utility);
    font-size: 0.66rem;
    font-variant-numeric: tabular-nums;
    font-weight: 700;
    letter-spacing: 0.06em;
    line-height: 1;
}

#shelter-stage-display::before {
    content: "90°S // 피난처";
    top: 8px;
    left: 8px;
}

#shelter-stage-display::after {
    content: "목표 // EXIT 0";
    right: 8px;
    bottom: 8px;
}

#btn-produce + div {
    margin-top: 24px !important;
}

.puzzle-tabs {
    min-width: 0;
    display: flex;
    gap: 4px;
    margin-top: 12px;
}

.tab-btn {
    flex: 1 1 0;
    min-width: 0;
    padding: 8px;
    background: var(--polar-void);
    border: 1px solid var(--signal-cyan);
    color: var(--snow-white);
    font-family: var(--font-utility);
    font-size: 0.76rem;
    font-weight: 700;
}

.tab-btn.active {
    background: var(--signal-cyan);
    border-color: var(--signal-cyan);
    color: var(--polar-void);
}

#puzzle-title {
    min-width: 0;
    margin: 12px 0 !important;
    overflow-wrap: anywhere;
    color: var(--signal-cyan) !important;
    font-family: var(--font-utility);
    font-variant-numeric: tabular-nums;
}

#puzzle-options {
    min-width: 0;
}

.puzzle-option {
    width: 100%;
    margin: 4px 0;
    padding: 12px;
    overflow-wrap: anywhere;
    background: var(--polar-void);
    border: 1px solid var(--signal-cyan);
    color: var(--snow-white);
    font-family: var(--font-utility);
    font-size: 0.82rem;
    font-variant-numeric: tabular-nums;
    line-height: 1.45;
    text-align: left;
    white-space: normal;
}

.puzzle-option:hover {
    background: var(--control-navy);
    border-color: var(--signal-cyan);
}

.upgrade-list {
    min-width: 0;
    margin-top: 12px;
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.upgrade-card {
    min-width: 0;
    padding: 12px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
    background: var(--polar-void);
    border: 1px solid var(--signal-cyan);
    border-radius: 4px;
}

.upgrade-copy {
    min-width: 0;
    flex: 1 1 auto;
}

.upgrade-name,
.upgrade-description {
    min-width: 0;
    overflow-wrap: anywhere;
}

.upgrade-name {
    font-family: var(--font-utility);
}

.upgrade-description {
    margin-top: 4px;
    color: var(--snow-white) !important;
    line-height: 1.45;
}

.upgrade-card .btn-touch {
    flex: 0 0 auto;
}

@keyframes dangerous-alliance-warning-light {
    0%,
    100% {
        box-shadow: 0 0 0 rgb(255 101 122 / 0%);
    }

    50% {
        box-shadow: 0 0 24px rgb(255 101 122 / 42%);
    }
}

.dangerous-alliance-overlay {
    position: fixed;
    z-index: 19;
    inset: 0;
    padding: 16px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: rgb(7 11 18 / 92%);
}

.dangerous-alliance-overlay[hidden] {
    display: none;
}

.dangerous-alliance-dialog {
    width: min(100%, 640px);
    max-height: calc(100dvh - 32px);
    padding: 24px;
    overflow-y: auto;
    overscroll-behavior: contain;
    background: var(--control-navy);
    border: 2px solid var(--alarm-coral);
    border-radius: 8px;
    animation: dangerous-alliance-warning-light 480ms ease-out 1;
    transition: border-color 160ms ease;
}

#dangerous-alliance-heading {
    color: var(--alarm-coral);
    font-size: 1.15rem;
    text-align: center;
}

#dangerous-alliance-image {
    width: 100%;
    height: auto;
    margin-top: 16px;
    display: block;
    aspect-ratio: 3 / 2;
    object-fit: cover;
    border: 1px solid var(--signal-cyan);
    border-radius: 4px;
}

.dangerous-alliance-summary {
    margin-top: 16px;
    color: var(--tuna-amber);
    font-family: var(--font-utility);
    font-weight: 800;
    text-align: center;
}

#dangerous-alliance-description {
    margin-top: 8px;
}

#btn-accept-alliance-result {
    width: 100%;
    margin-top: 16px;
}

.ending-overlay {
    position: fixed;
    z-index: 20;
    inset: 0;
    padding: 16px;
    align-items: center;
    justify-content: center;
    background: var(--polar-void);
}

.ending-dialog {
    width: min(100%, 480px);
    max-height: calc(100dvh - 32px);
    padding: 24px;
    overflow-y: auto;
    overscroll-behavior: contain;
    background: var(--control-navy);
    border: 1px solid var(--signal-cyan);
    border-radius: 8px;
    text-align: center;
}

.ending-process-heading,
.ending-financial-heading {
    font-size: 1rem;
}

.ending-process-code,
.ending-financial-code {
    margin-top: 8px;
    padding: 12px;
    background: var(--polar-void);
    border-radius: 4px;
    font-family: var(--font-utility);
    font-size: 0.9rem;
    font-variant-numeric: tabular-nums;
    font-weight: 800;
}

.ending-process-code {
    color: var(--signal-cyan);
}

.ending-financial-heading {
    margin-top: 16px;
}

.ending-financial-code,
.ending-net-balance,
.ending-incident-cost {
    color: var(--alarm-coral);
}

.ending-summary {
    margin-top: 16px;
    display: grid;
    gap: 4px;
    font-family: var(--font-utility);
    font-size: 0.82rem;
    font-variant-numeric: tabular-nums;
}

.ending-divider {
    margin: 16px 0;
    border: 0;
    border-top: 1px solid rgba(81, 210, 246, 0.45);
}

.ending-acquisition-image {
    display: block;
    width: 100%;
    height: auto;
    aspect-ratio: 1672 / 941;
    border: 1px solid rgba(81, 210, 246, 0.45);
    border-radius: 6px;
}

.ending-offer,
.ending-title {
    margin-top: 12px;
}

.btn-play-again {
    width: 100%;
    margin-top: 16px;
    background: var(--signal-cyan);
    border-color: var(--signal-cyan);
    color: var(--polar-void);
}

@media (max-width: 768px) {
    .dashboard {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }

    .main-grid {
        grid-template-columns: minmax(0, 1fr);
    }
}

@media (max-width: 480px) {
    .dashboard {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .upgrade-card {
        align-items: stretch;
        flex-direction: column;
    }

    .upgrade-card .btn-touch {
        width: 100%;
    }
}

@media (max-width: 320px) {
    body {
        padding: 8px;
    }

    header {
        margin-bottom: 12px;
    }

    h1 {
        font-size: 1.45rem;
    }

    h1::before {
        font-size: 0.58rem;
    }

    .sub {
        font-size: 0.72rem;
    }

    .card {
        padding: 8px;
    }

    .panel {
        padding: 12px;
    }

    .btn-touch {
        padding: 12px;
        font-size: 0.82rem;
    }

    .puzzle-tabs {
        flex-wrap: wrap;
    }

    .tab-btn {
        flex-basis: calc(50% - 4px);
    }

    .dangerous-alliance-overlay,
    .ending-overlay {
        padding: 8px;
    }

    .dangerous-alliance-dialog,
    .ending-dialog {
        max-height: calc(100dvh - 16px);
        padding: 16px;
    }
}

@media (max-height: 400px) {
    .dangerous-alliance-dialog,
    .ending-dialog {
        padding: 12px;
    }

    .ending-process-code,
    .ending-financial-code {
        margin-top: 4px;
        padding: 8px;
    }

    .ending-financial-heading,
    .ending-summary,
    .btn-play-again {
        margin-top: 8px;
    }
}

@media (prefers-reduced-motion: reduce) {
    *,
    *::before,
    *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
    }

    .dangerous-alliance-dialog {
        animation: none !important;
        transition: none !important;
    }

    body.intrusion-impact--copilot > header,
    body.intrusion-impact--copilot > .dashboard,
    body.intrusion-impact--copilot > .intrusion-banner,
    body.intrusion-impact--copilot > .main-grid,
    body.intrusion-impact--codex > header,
    body.intrusion-impact--codex > .dashboard,
    body.intrusion-impact--codex > .intrusion-banner,
    body.intrusion-impact--codex > .main-grid,
    body.intrusion-impact--gemini > header,
    body.intrusion-impact--gemini > .dashboard,
    body.intrusion-impact--gemini > .intrusion-banner,
    body.intrusion-impact--gemini > .main-grid,
    body.intrusion-impact--ceo > header,
    body.intrusion-impact--ceo > .dashboard,
    body.intrusion-impact--ceo > .intrusion-banner,
    body.intrusion-impact--ceo > .main-grid {
        animation: none !important;
        transform: none !important;
        will-change: auto !important;
    }
}

.puzzle-description,
.terminal-output,
.npc-card,
.quote-collection {
    margin-top: 10px;
}

.puzzle-description,
.quote-collection {
    color: #94a3b8;
    font-size: 0.78rem;
}

.terminal-output {
    height: clamp(14rem, 30vh, 18rem);
    overflow-y: auto;
    padding: 8px;
    border: 1px solid #1e3a5f;
    background: #07111f;
    color: #dbeafe;
    font: 0.76rem/1.45 var(--font-utility);
}

.terminal-line + .terminal-line {
    margin-top: 3px;
}

.terminal-line {
    white-space: pre-wrap;
    overflow-wrap: anywhere;
    word-break: break-word;
}

.terminal-line[data-terminal-kind="command"] {
    margin-top: 8px;
    color: #54c7ec;
    font-weight: 700;
}

.terminal-line[data-terminal-kind="system"] {
    color: #94a3b8;
    font-weight: 400;
}

.terminal-line[data-terminal-kind="archon"] {
    margin: 8px 0;
    padding: 8px;
    border-left: 3px solid #ff657a;
    background: #1a1018;
    color: #ffe4e8;
    font: 700 0.82rem/1.58 var(--font-utility);
}

.terminal-line[data-terminal-kind="archon"]::before {
    content: "ARCHON // ROAST";
    display: block;
    color: #f6b83f;
}

@media (max-width: 480px) {
    .terminal-output {
        height: 15rem;
    }
}

@media (max-height: 400px) {
    .terminal-output {
        height: 10rem;
    }
}

.npc-card {
    display: flex;
    gap: 8px;
    align-items: flex-start;
    padding: 8px;
    border: 1px solid #0f766e;
    background: #062b2b;
    color: #ccfbf1;
    font-size: 0.78rem;
}

.npc-card[hidden] {
    display: none;
}

.npc-icon {
    font-size: 1.4rem;
}

.npc-card p {
    margin: 3px 0 0;
}
